   171		if dirty && !indexOpts.worktree {
   172			return errors.New("dirty_worktree: refusing to index uncommitted content without --worktree")
   173		}
   174	
   175		var raw []byte
   176		var header semanticHeader
   177		counts := semanticCounts{}
   178		noEgress := false
   179		var warnings []semanticWarning
   180		for _, warning := range defaultWarnings {
   181			warnings = append(warnings, semanticWarning{Code: "default_branch_unknown", Severity: "warning", Effect: "freshness", Detail: warning})
   182		}
   183		if indexOpts.skipSem {
   184			header = semanticHeader{
   185				SchemaVersion: "1.0",
   186				Provider:      "skipped",
   187				RepoRoot:      repoDir,
   188				RepoKey:       storage.Key,
   189				Commit:        head,
   190				Tree:          tree,
   191				Warnings:      []semanticWarning{{Code: "provider_skipped", Severity: "warning", Effect: "semantic facts unavailable", Detail: "semantic provider was skipped"}},
   192			}
   193			raw, err = json.Marshal(header)
   194			if err != nil {
   195				return err
   196			}
   197			raw = append(raw, '\n')
   198			warnings = append(warnings, header.Warnings...)
   199		} else {
   200			if strings.TrimSpace(indexOpts.semBinary) == "" {
   201				return errors.New("--sem-binary must not be empty")
   202			}
   203			var doctorWarnings []semanticWarning
   204			noEgress, doctorWarnings = runSemanticDoctor(ctx, opts.Runner, repoDir, indexOpts.semBinary)
   205			warnings = append(warnings, doctorWarnings...)
   206			if !noEgress {
   207				code := "provider_no_egress_unverified"
   208				if len(doctorWarnings) > 0 && doctorWarnings[0].Code != "" {
   209					code = doctorWarnings[0].Code
   210				}
   211				return fmt.Errorf("%s: semantic provider no-egress status is not verified", code)
   212			}
   213			raw, err = runSemanticSnapshot(ctx, opts.Runner, repoDir, indexOpts.semBinary)
   214			if err != nil {
   215				return err
   216			}
   217			header, counts, raw, err = filterSemanticSnapshot(raw, ignore)
   218			if err != nil {
   219				return err
   220			}
   221			if err := validateSemanticSchema(header.SchemaVersion); err != nil {
   222				return err
   223			}
   224			warnings = append(warnings, header.Warnings...)
   225		}
   226		if header.Commit == "" {
   227			header.Commit = head
   228		}
   229		if header.Tree == "" {
   230			header.Tree = tree
   231		}
   232		if header.Provider == "" {
   233			header.Provider = "entire-sem"
   234		}
   235		if header.RepoKey == "" {
   236			header.RepoKey = storage.Key
   237		}
   238	
   239		snapshotID := header.Commit
   240		worktreeMode := "head"
   241		worktreeHash := ""
   242		if indexOpts.worktree {
   243			sum := sha256.Sum256(raw)
   244			snapshotID = "worktree-" + hex.EncodeToString(sum[:8])
   245			worktreeMode = "worktree"
   246			worktreeHash = worktreeFingerprint(ctx, opts.Runner, repoDir)
   247		} else if snapshotID == "" {
   248			snapshotID = "unknown"
   249		}
   250		snapshotRel := filepath.ToSlash(filepath.Join(semanticDirName, semanticSnapshotsDir, snapshotID, semanticSnapshotName))
   251		snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(snapshotRel))
   252		if err := writeFileAtomic(snapshotPath, raw, 0o600); err != nil {
   253			return fmt.Errorf("write semantic snapshot: %w", err)
   254		}
   255		source := &semanticSourceManifest{
   256			GeneratedAt:      opts.Now().UTC(),
   257			Commit:           header.Commit,
   258			Tree:             header.Tree,
   259			Branch:           branch,
   260			DefaultBranch:    defaultBranch,
   320				return nil, fmt.Errorf("index_locked: semantic index lock exists at %s", lockPath)
   321			}
   322			return nil, fmt.Errorf("create semantic index lock: %w", err)
   323		}
   324		_, _ = fmt.Fprintf(f, "pid=%d\ncreated_at=%s\n", os.Getpid(), time.Now().UTC().Format(time.RFC3339))
   325		_ = f.Close()
   326		return func() { _ = os.Remove(lockPath) }, nil
   327	}
