   329	func runSemanticDoctor(ctx context.Context, runner CommandRunner, repoDir, semBinary string) (bool, []semanticWarning) {
   330		stdout, _, err := runner.Run(ctx, repoDir, semBinary, "sem", "doctor", "--json")
   331		if err != nil {
   332			return false, []semanticWarning{{Code: "provider_doctor_failed", Severity: "warning", Effect: "provider diagnostics unavailable", Detail: err.Error()}}
   333		}
   334		var data map[string]any
   335		if err := json.Unmarshal(stdout, &data); err != nil {
   336			return false, []semanticWarning{{Code: "provider_doctor_malformed", Severity: "warning", Effect: "provider diagnostics unavailable", Detail: err.Error()}}
   337		}
   338		if boolValue(data, "network_egress") || boolValue(data, "requires_network") || boolValue(data, "network_required") {
   339			return false, []semanticWarning{{Code: "provider_network_required", Severity: "error", Effect: "phase 1 local-only guarantee not verified", Detail: "provider doctor reports network access is required"}}
   340		}
   341		if boolValue(data, "no_egress") || boolValue(data, "no_egress_verified") || boolValue(data, "local_only") {
   342			return true, nil
   343		}
   344		return false, []semanticWarning{{Code: "provider_no_egress_unknown", Severity: "warning", Effect: "phase 1 local-only guarantee not fully verified", Detail: "provider doctor did not report no-egress status"}}
   345	}
