   356	func runSemanticSnapshot(ctx context.Context, runner CommandRunner, repoDir, semBinary string) ([]byte, error) {
   357		stdout, _, err := runner.Run(ctx, repoDir, semBinary, "sem", "snapshot", "--repo", repoDir, "--format", "ndjson")
   358		if err != nil {
   359			return nil, fmt.Errorf("semantic provider snapshot failed: %w", err)
   360		}
   361		if len(bytes.TrimSpace(stdout)) == 0 {
   362			return nil, errors.New("semantic provider snapshot produced no output")
   363		}
   364		return stdout, nil
   365	}
