   367	func filterSemanticSnapshot(raw []byte, ignore brainIgnore) (semanticHeader, semanticCounts, []byte, error) {
   368		scanner := bufio.NewScanner(bytes.NewReader(raw))
   369		scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
   370		if !scanner.Scan() {
   371			if err := scanner.Err(); err != nil {
   372				return semanticHeader{}, semanticCounts{}, nil, err
   373			}
   374			return semanticHeader{}, semanticCounts{}, nil, errors.New("semantic snapshot missing header")
   375		}
   376		headerLine := append([]byte(nil), scanner.Bytes()...)
   377		var header semanticHeader
   378		if err := json.Unmarshal(scanner.Bytes(), &header); err != nil {
   379			return semanticHeader{}, semanticCounts{}, nil, fmt.Errorf("parse semantic snapshot header: %w", err)
   380		}
   381		type parsedLine struct {
   382			record semanticRecord
   383			raw    []byte
   384		}
   385		var lines []parsedLine
   386		ignoredIDs := make(map[string]struct{})
   387		line := 1
   388		for scanner.Scan() {
   389			line++
   390			text := bytes.TrimSpace(scanner.Bytes())
   391			if len(text) == 0 {
   392				continue
   393			}
   394			var record semanticRecord
   395			if err := json.Unmarshal(text, &record); err != nil {
   396				return semanticHeader{}, semanticCounts{}, nil, fmt.Errorf("parse semantic snapshot line %d: %w", line, err)
   397			}
   398			if ignore.Ignored(record.semanticPath()) && record.ID != "" {
   399				ignoredIDs[record.ID] = struct{}{}
   400			}
   401			lines = append(lines, parsedLine{record: record, raw: append([]byte(nil), text...)})
   402		}
   403		if err := scanner.Err(); err != nil {
   404			return semanticHeader{}, semanticCounts{}, nil, err
   405		}
   406		var filtered bytes.Buffer
   407		filtered.Write(headerLine)
   408		filtered.WriteByte('\n')
   409		var counts semanticCounts
   410		for _, line := range lines {
   411			record := line.record
   412			if ignore.Ignored(record.semanticPath()) {
   413				continue
   414			}
   415			if record.RecordType == "relation" {
   416				if _, ok := ignoredIDs[record.FromID]; ok {
   417					continue
   418				}
   419				if _, ok := ignoredIDs[record.ToID]; ok {
   420					continue
   421				}
   422			}
   423			switch record.RecordType {
   424			case "symbol":
   425				counts.Symbols++
   426			case "relation":
   427				counts.Relations++
   428			}
   429			filtered.Write(line.raw)
   430			filtered.WriteByte('\n')
   520		sum := sha256.Sum256(append(status, diff...))
   521		return "sha256:" + hex.EncodeToString(sum[:])
   522	}
