   588	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
   589		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
   590		if err != nil {
   591			return staleReport{}, err
   592		}
   593		if !local {
   594			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
   595		}
   596		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
   597		if err != nil {
   598			return staleReport{}, err
   599		}
   600		manifest, err := loadBrainManifest(storage.BrainDir)
   601		if err != nil {
   602			return staleReport{}, err
   603		}
   604		axes := map[string]staleAxis{}
   605		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
   606			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
   607			return staleReport{Severity: "unsafe", Axes: axes}, nil
   608		}
   609		source := manifest.Sources.Semantic
   610		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
   611		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
   612		dirty := worktreeDirty(ctx, opts.Runner, repoDir)
   613		if source.Commit == head {
   614			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
   615		} else {
   616			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
   617		}
   618		if source.Branch == "" || source.Branch == branch {
   619			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
   620		} else {
   621			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
   622		}
   623		switch {
   624		case dirty && source.WorktreeMode != "worktree":
   625			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
   626		case dirty && source.WorktreeHash != "" && source.WorktreeHash != worktreeFingerprint(ctx, opts.Runner, repoDir):
   627			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
   628		case dirty:
   629			axes["worktree"] = staleAxis{State: "dirty-indexed"}
   630		default:
   631			axes["worktree"] = staleAxis{State: "clean"}
   632		}
   633		if err := validateSemanticSchema(source.SchemaVersion); err != nil {
   634			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
   635		} else if !source.NoEgressVerified {
   636			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
   637		} else {
   638			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
   639		}
   640		if len(source.PartialFailures) > 0 {
   641			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
   642		} else {
   643			axes["semantic_completeness"] = staleAxis{State: "ok"}
   644		}
   645		severity := aggregateStaleSeverity(axes)
   646		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
   647	}
   648	
   649	func aggregateStaleSeverity(axes map[string]staleAxis) string {
   650		severity := "ok"
   651		for _, axis := range axes {
   652			switch axis.State {
   653			case "missing", "unsafe", "stale", "dirty-stale":
   654				return "unsafe"
   655			case "degraded", "dirty-unindexed":
   656				severity = "degraded"
   657			}
   658		}
   659		return severity
   660	}
