   784	func runSemanticGC(ctx context.Context, cmd *cobra.Command, opts Options, target, olderThan string) error {
   785		cutoff, err := parseAgeCutoff(olderThan, opts.Now().UTC())
   786		if err != nil {
   787			return err
   788		}
   789		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
   790		if err != nil {
   791			return err
   792		}
   793		if !local {
   794			return fmt.Errorf("gc requires a local repository path: %s", target)
   795		}
   796		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
   797		if err != nil {
   798			return err
   799		}
   800		manifest, _ := loadBrainManifest(storage.BrainDir)
   801		active := ""
   802		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil {
   803			active = filepath.Clean(filepath.Join(storage.BrainDir, filepath.FromSlash(manifest.Sources.Semantic.SnapshotPath), ".."))
   804		}
   805		snapshotsRoot := filepath.Join(storage.BrainDir, semanticDirName, semanticSnapshotsDir)
   806		entries, err := os.ReadDir(snapshotsRoot)
   807		if err != nil {
   808			if os.IsNotExist(err) {
   809				fmt.Fprintln(cmd.OutOrStdout(), "pruned semantic snapshots: 0")
   810				return nil
   811			}
   812			return err
   813		}
   814		pruned := 0
   815		for _, entry := range entries {
   816			if !entry.IsDir() {
   817				continue
   818			}
   819			path := filepath.Join(snapshotsRoot, entry.Name())
   820			if active != "" && filepath.Clean(path) == active {
   821				continue
   822			}
   823			info, err := entry.Info()
   824			if err != nil {
   825				continue
   826			}
   827			if info.ModTime().Before(cutoff) {
   828				if err := os.RemoveAll(path); err != nil {
   829					return err
   830				}
   831				pruned++
   832			}
   833		}
   834		fmt.Fprintf(cmd.OutOrStdout(), "pruned semantic snapshots: %d\n", pruned)
   835		return nil
   836	}
   837	
   838	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
   839		value = strings.TrimSpace(value)
   840		if strings.HasSuffix(value, "d") {
   841			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
   842			if err != nil || days < 0 {
   843				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   844			}
   845			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
   846		}
   847		duration, err := time.ParseDuration(value)
   848		if err != nil {
   849			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   850		}
   851		return now.Add(-duration), nil
   852	}
